/**
 *
 * DataTableRow is a component that displays a row inside a DataTable.
 *
 * [Live Demo](https://www.primereact.org/datatable/)
 *
 * @module DataTableRow
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { UseDataTableRowMouseEvent } from '@primereact/types/headless/datatable';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { DataTableRootInstance } from './DataTableRoot.types';
/**
 * Defines passthrough(pt) options type in DataTableRow component.
 */
export type DataTableRowPassThroughType<E> = PassThroughType<DataTableRowInstance, E>;
/**
 * Defines passthrough(pt) options of DataTableRow component.
 */
export interface DataTableRowPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: DataTableRowPassThroughType<React.HTMLAttributes<HTMLTableRowElement>>;
}
/**
 * Defines valid properties in DataTableRow component.
 */
export interface DataTableRowProps extends BaseComponentProps<DataTableRowInstance, unknown, DataTableRowPassThrough, 'tr'> {
    /**
     * Zero-based index of the row. Used for `aria-rowindex`, striped-row class, and keyboard navigation tab order.
     * When the row is rendered inside a data-driven `TBody` iteration the index is derived from the context;
     * pass this prop explicitly when rendering rows outside of that flow (for example, when iterating data manually).
     * @default undefined
     */
    index?: number | undefined;
}
/**
 * Defines valid state in DataTableRow component.
 */
export interface DataTableRowState {
}
/**
 * Defines the methods and properties exposed by DataTableRow component.
 */
export interface DataTableRowExposes {
    /**
     * The DataTable component instance.
     */
    datatable: DataTableRootInstance | undefined | null;
}
/**
 * Instance of DataTableRow component.
 */
export type DataTableRowInstance = ComponentInstance<DataTableRowProps, DataTableRowState, DataTableRowExposes>;
/**
 * Event re-exported from the headless layer so consumers can import it from the
 * primitive/UI barrel instead of reaching into headless. Mirrors `UseDataTableRowMouseEvent`.
 */
export interface DataTableRowMouseEvent extends UseDataTableRowMouseEvent {
}
